class StockAnalyzer{constructor(t={}){this.proxy=t.proxy||"https://api.allorigins.win/get?url=",this.libUrl="https://unpkg.com/lightweight-charts/dist/lightweight-charts.standalone.production.js",this.data=[],this.symbol="",this._libPromise=this._loadLibrary()}async _loadLibrary(){if(window.LightweightCharts)return window.LightweightCharts;return new Promise(((t,e)=>{const s=document.createElement("script");s.src=this.libUrl,s.onload=()=>t(window.LightweightCharts),s.onerror=()=>e(new Error("Lib Load Fail")),document.head.appendChild(s)}))}async fetch(t){this.symbol=/^\d+$/.test(t)?`${t.padStart(4,"0")}.HK`:t.toUpperCase();const e=`https://query1.finance.yahoo.com/v8/finance/chart/${this.symbol}?range=3mo&interval=1d`;try{const t=await fetch(`${this.proxy}${encodeURIComponent(e)}`),s=await t.json(),i=JSON.parse(s.contents).chart.result[0],r=i.indicators.quote[0];return this.data=i.timestamp.map(((t,e)=>({time:t,open:r.open[e],high:r.high[e],low:r.low[e],close:r.close[e]}))).filter((t=>null!==t.close)),this}catch(t){throw t}}async render(t){const e=await this._libPromise,s=document.getElementById(t),i=e.createChart(s,{width:s.clientWidth,height:500,layout:{background:{color:"#ffffff"},textColor:"#333"},timeScale:{borderColor:"#D1D4DC",barSpacing:10}});return i.addCandlestickSeries({upColor:"#ef5350",downColor:"#26a69a",borderUpColor:"#ef5350",borderDownColor:"#26a69a",wickUpColor:"#ef5350",wickDownColor:"#26a69a"}).setData(this.data),i.timeScale().fitContent(),this.symbol}}
